import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import SimpleButton from '../components/SimpleButton';

const SimpleCAMPreview = () => {
  const navigate = useNavigate();
  const [camFiles, setCamFiles] = useState([]);
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState('');
  const [companyData, setCompanyData] = useState(null);

  useEffect(() => {
    // Load company data from localStorage
    const storedCompanyData = localStorage.getItem('companyData');
    if (storedCompanyData) {
      setCompanyData(JSON.parse(storedCompanyData));
    }
  }, []);

  const handleGenerateCAM = async () => {
    if (!companyData) {
      setError('No company data available. Please upload documents first.');
      return;
    }

    setGenerating(true);
    setError('');

    try {
      // Generate CAM content based on company data
      const camContent = generateCAMContent(companyData);

      // Create and download the CAM file
      const blob = new Blob([camContent], { type: 'text/plain' });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `CAM_${companyData.company.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.txt`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);

      // Add to CAM files list
      const newCAMFile = {
        id: Date.now(),
        filename: link.download,
        company: companyData.company,
        generated_at: new Date().toISOString(),
        size: blob.size
      };
      setCamFiles([...camFiles, newCAMFile]);

    } catch (err) {
      setError('Failed to generate CAM: ' + err.message);
    } finally {
      setGenerating(false);
    }
  };

  const generateCAMContent = (data) => {
    const currentDate = new Date().toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });

    return `
CREDIT APPRAISAL MEMORANDUM (CAM)
=====================================

Company: ${data.company}
Industry: ${data.industry || 'N/A'}
Date: ${currentDate}
Generated by: AI Credit Decisioning Engine

EXECUTIVE SUMMARY
=================
This Credit Appraisal Memorandum provides a comprehensive analysis of ${data.company}'s creditworthiness based on financial performance, risk assessment, and industry dynamics.

FINANCIAL OVERVIEW
==================
Revenue: ₹${(data.revenue / 10000000).toFixed(2)} Crores
Profit: ₹${(data.profit / 10000000).toFixed(2)} Crores
Total Assets: ₹${(data.assets / 10000000).toFixed(2)} Crores
Total Liabilities: ₹${(data.liabilities / 10000000).toFixed(2)} Crores

Financial Ratios:
- Profit Margin: ${data.financial_ratios?.profit_margin?.toFixed(2) || 'N/A'}%
- Debt-to-Assets Ratio: ${data.financial_ratios?.debt_to_assets?.toFixed(2) || 'N/A'}%
- Return on Assets: ${data.financial_ratios?.return_on_assets?.toFixed(2) || 'N/A'}%

RISK ASSESSMENT
===============
Risk Score: ${data.ai_analysis?.risk_analysis?.risk_score || 'N/A'}/100
Risk Category: ${data.ai_analysis?.risk_analysis?.risk_category || 'N/A'}
Confidence Score: ${((data.ai_analysis?.risk_analysis?.confidence_score || 0) * 100).toFixed(1)}%

Key Risk Factors:
${data.ai_analysis?.risk_factors?.map((factor, index) => 
  `${index + 1}. ${typeof factor === 'string' ? factor : factor.description}`
).join('\n') || 'No significant risk factors identified.'}

CREDIT DECISION
===============
Recommended Decision: ${data.ai_analysis?.decision_result?.decision || 'N/A'}
Confidence Level: ${((data.ai_analysis?.decision_result?.confidence_score || 0) * 100).toFixed(1)}%

Loan Analysis:
- Approved Loan Amount: ₹${(data.ai_analysis?.loan_analysis?.approved_loan_amount / 10000000).toFixed(2)} Crores
- Interest Rate: ${data.ai_analysis?.loan_analysis?.interest_rate || 'N/A'}%
- Recommended Tenure: ${data.ai_analysis?.loan_analysis?.recommended_tenure || 'N/A'} months

DECISION REASONING
=================
${data.ai_analysis?.decision_result?.reasoning || 'No reasoning provided.'}

RECOMMENDED ACTIONS
==================
${data.ai_analysis?.decision_result?.recommended_actions?.map((action, index) => 
  `${index + 1}. ${action}`
).join('\n') || 'No specific actions recommended.'}

INDUSTRY ANALYSIS
=================
Industry: ${data.industry || 'N/A'}
Market Position: ${data.ai_analysis?.research_summary?.industry_analysis?.market_position || 'N/A'}
Industry Outlook: ${data.ai_analysis?.research_summary?.industry_analysis?.outlook || 'N/A'}
Growth Rate: ${data.ai_analysis?.research_summary?.industry_analysis?.growth_rate || 'N/A'}

RESEARCH INSIGHTS
=================
News Sentiment: ${data.ai_analysis?.research_summary?.news_sentiment?.sentiment || 'N/A'}
Sentiment Score: ${data.ai_analysis?.research_summary?.news_sentiment?.score?.toFixed(2) || 'N/A'}
Litigation Risk: ${data.ai_analysis?.research_summary?.litigation_data?.risk_assessment || 'N/A'}

CONCLUSION
===========
Based on the comprehensive analysis, ${data.company} demonstrates ${data.ai_analysis?.decision_result?.decision === 'Approve' ? 'strong' : data.ai_analysis?.decision_result?.decision === 'Reject' ? 'weak' : 'moderate'} creditworthiness with a risk profile categorized as ${data.ai_analysis?.risk_analysis?.risk_category || 'N/A'}.

The recommended credit facility of ₹${(data.ai_analysis?.loan_analysis?.approved_loan_amount / 10000000).toFixed(2)} Crores at ${data.ai_analysis?.loan_analysis?.interest_rate || 'N/A'}% interest rate is justified based on the company's financial performance and risk parameters.

This CAM was generated using AI-powered analysis algorithms and should be reviewed by credit committee before final approval.

=====================================
End of Credit Appraisal Memorandum
Generated: ${new Date().toISOString()}
    `.trim();
  };

  if (generating) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f0f9ff' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ 
            width: '48px', 
            height: '48px', 
            border: '4px solid #e5e7eb', 
            borderTop: '4px solid #2563eb', 
            borderRadius: '50%', 
            animation: 'spin 1s linear infinite',
            margin: '0 auto 16px'
          }}></div>
          <p style={{ fontSize: '18px', color: '#4b5563' }}>Generating CAM Report...</p>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#f0f9ff', padding: '32px 0' }}>
      <div style={{ maxWidth: '1280px', margin: '0 auto', padding: '0 16px' }}>
        {/* Header */}
        <div style={{ marginBottom: '32px' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <div>
              <h1 style={{ fontSize: '32px', fontWeight: 'bold', color: '#111827', marginBottom: '8px', display: 'flex', alignItems: 'center' }}>
                <span style={{ marginRight: '12px' }}>📄</span>
                Credit Appraisal Memo (CAM)
              </h1>
              <p style={{ fontSize: '18px', color: '#6b7280' }}>
                Generate and download comprehensive credit analysis reports
              </p>
            </div>
            <div style={{ display: 'flex', gap: '12px' }}>
              <SimpleButton
                onClick={() => navigate('/dashboard')}
                style={{ backgroundColor: '#2563eb', color: 'white' }}
              >
                📊 Back to Dashboard
              </SimpleButton>
            </div>
          </div>
        </div>

        {/* Company Information */}
        {companyData && (
          <div style={{ 
            backgroundColor: 'white', 
            padding: '32px', 
            borderRadius: '16px', 
            marginBottom: '32px',
            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
            border: '1px solid #e5e7eb'
          }}>
            <h3 style={{ fontSize: '24px', fontWeight: 'bold', color: '#111827', marginBottom: '24px', display: 'flex', alignItems: 'center' }}>
              <span style={{ marginRight: '12px' }}>🏢</span>
              Company Information
            </h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '24px' }}>
              <div style={{ padding: '16px', backgroundColor: '#f9fafb', borderRadius: '8px' }}>
                <p style={{ fontSize: '14px', color: '#6b7280', marginBottom: '4px' }}>Company Name</p>
                <p style={{ fontSize: '18px', fontWeight: 'bold', color: '#111827' }}>{companyData.company}</p>
              </div>
              <div style={{ padding: '16px', backgroundColor: '#f9fafb', borderRadius: '8px' }}>
                <p style={{ fontSize: '14px', color: '#6b7280', marginBottom: '4px' }}>Industry</p>
                <p style={{ fontSize: '18px', fontWeight: 'bold', color: '#111827' }}>{companyData.industry || 'N/A'}</p>
              </div>
              <div style={{ padding: '16px', backgroundColor: '#f9fafb', borderRadius: '8px' }}>
                <p style={{ fontSize: '14px', color: '#6b7280', marginBottom: '4px' }}>Revenue</p>
                <p style={{ fontSize: '18px', fontWeight: 'bold', color: '#111827' }}>
                  ₹{(companyData.revenue / 10000000).toFixed(1)}Cr
                </p>
              </div>
              <div style={{ padding: '16px', backgroundColor: '#f9fafb', borderRadius: '8px' }}>
                <p style={{ fontSize: '14px', color: '#6b7280', marginBottom: '4px' }}>Risk Score</p>
                <p style={{ fontSize: '18px', fontWeight: 'bold', color: '#111827' }}>
                  {companyData.ai_analysis?.risk_analysis?.risk_score || 'N/A'}/100
                </p>
              </div>
            </div>
          </div>
        )}

        {/* CAM Generation Section */}
        <div style={{ 
          backgroundColor: 'white', 
          padding: '32px', 
          borderRadius: '16px', 
          marginBottom: '32px',
          boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
          border: '1px solid #e5e7eb'
        }}>
          <h3 style={{ fontSize: '24px', fontWeight: 'bold', color: '#111827', marginBottom: '24px', display: 'flex', alignItems: 'center' }}>
            <span style={{ marginRight: '12px' }}>📋</span>
            Generate CAM Report
          </h3>

          <div style={{ marginBottom: '24px' }}>
            <p style={{ fontSize: '16px', color: '#374151', marginBottom: '16px' }}>
              Generate a comprehensive Credit Appraisal Memorandum (CAM) containing detailed financial analysis, 
              risk assessment, and credit recommendations for {companyData?.company || 'the selected company'}.
            </p>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px', marginBottom: '24px' }}>
              <div style={{ 
                padding: '16px', 
                backgroundColor: '#dbeafe', 
                borderRadius: '8px',
                border: '1px solid #93c5fd'
              }}>
                <div style={{ fontSize: '24px', marginBottom: '8px' }}>📊</div>
                <h4 style={{ fontWeight: 'bold', color: '#1e40af', marginBottom: '4px' }}>Financial Analysis</h4>
                <p style={{ fontSize: '14px', color: '#1e40af' }}>Comprehensive financial metrics and ratios</p>
              </div>
              <div style={{ 
                padding: '16px', 
                backgroundColor: '#d1fae5', 
                borderRadius: '8px',
                border: '1px solid #6ee7b7'
              }}>
                <div style={{ fontSize: '24px', marginBottom: '8px' }}>🛡️</div>
                <h4 style={{ fontWeight: 'bold', color: '#065f46', marginBottom: '4px' }}>Risk Assessment</h4>
                <p style={{ fontSize: '14px', color: '#065f46' }}>AI-powered risk evaluation and scoring</p>
              </div>
              <div style={{ 
                padding: '16px', 
                backgroundColor: '#fef3c7', 
                borderRadius: '8px',
                border: '1px solid #fde68a'
              }}>
                <div style={{ fontSize: '24px', marginBottom: '8px' }}>🎯</div>
                <h4 style={{ fontWeight: 'bold', color: '#92400e', marginBottom: '4px' }}>Credit Decision</h4>
                <p style={{ fontSize: '14px', color: '#92400e' }}>Recommendations with confidence scores</p>
              </div>
              <div style={{ 
                padding: '16px', 
                backgroundColor: '#f3e8ff', 
                borderRadius: '8px',
                border: '1px solid #d8b4fe'
              }}>
                <div style={{ fontSize: '24px', marginBottom: '8px' }}>📈</div>
                <h4 style={{ fontWeight: 'bold', color: '#6b21a8', marginBottom: '4px' }}>Industry Insights</h4>
                <p style={{ fontSize: '14px', color: '#6b21a8' }}>Market analysis and competitive position</p>
              </div>
            </div>
          </div>

          <div style={{ textAlign: 'center' }}>
            <button
              onClick={handleGenerateCAM}
              disabled={!companyData || generating}
              style={{
                padding: '16px 32px',
                borderRadius: '8px',
                fontSize: '18px',
                fontWeight: 'bold',
                border: 'none',
                cursor: !companyData || generating ? 'not-allowed' : 'pointer',
                backgroundColor: !companyData || generating ? '#d1d5db' : '#10b981',
                color: 'white',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)'
              }}
              onMouseEnter={(e) => {
                if (!(!companyData || generating)) {
                  e.target.style.backgroundColor = '#059669';
                  e.target.style.transform = 'translateY(-2px)';
                  e.target.style.boxShadow = '0 6px 8px rgba(0, 0, 0, 0.15)';
                }
              }}
              onMouseLeave={(e) => {
                if (!(!companyData || generating)) {
                  e.target.style.backgroundColor = '#10b981';
                  e.target.style.transform = 'translateY(0)';
                  e.target.style.boxShadow = '0 4px 6px rgba(0, 0, 0, 0.1)';
                }
              }}
            >
              {generating ? (
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <div style={{ 
                    width: '20px', 
                    height: '20px', 
                    border: '2px solid #ffffff', 
                    borderTop: '2px solid transparent', 
                    borderRadius: '50%', 
                    animation: 'spin 1s linear infinite'
                  }}></div>
                  <span>Generating CAM...</span>
                </div>
              ) : (
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span>📄</span>
                  <span>Generate CAM Report</span>
                </div>
              )}
            </button>
            {!companyData && (
              <p style={{ fontSize: '14px', color: '#ef4444', marginTop: '16px' }}>
                ⚠️ Please upload documents first to generate CAM report
              </p>
            )}
          </div>
        </div>

        {/* CAM Files List */}
        {camFiles.length > 0 && (
          <div style={{ 
            backgroundColor: 'white', 
            padding: '32px', 
            borderRadius: '16px',
            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
            border: '1px solid #e5e7eb'
          }}>
            <h3 style={{ fontSize: '24px', fontWeight: 'bold', color: '#111827', marginBottom: '24px', display: 'flex', alignItems: 'center' }}>
              <span style={{ marginRight: '12px' }}>📁</span>
              Generated CAM Reports
            </h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              {camFiles.map((file) => (
                <div
                  key={file.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    padding: '16px',
                    backgroundColor: '#f9fafb',
                    borderRadius: '8px',
                    border: '1px solid #e5e7eb'
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <div style={{ fontSize: '24px' }}>📄</div>
                    <div>
                      <p style={{ fontWeight: '600', color: '#111827' }}>{file.filename}</p>
                      <p style={{ fontSize: '14px', color: '#6b7280' }}>
                        {file.company} • {new Date(file.generated_at).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                  <button
                    onClick={() => handleGenerateCAM()}
                    style={{
                      backgroundColor: '#2563eb',
                      color: 'white',
                      padding: '8px 16px',
                      borderRadius: '6px',
                      border: 'none',
                      cursor: 'pointer',
                      fontSize: '14px',
                      fontWeight: '600'
                    }}
                  >
                    Download
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Error Message */}
        {error && (
          <div style={{ 
            marginTop: '24px', 
            padding: '16px', 
            backgroundColor: '#fef2f2', 
            border: '1px solid #fecaca',
            borderRadius: '8px'
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <div style={{ fontSize: '24px' }}>⚠️</div>
              <div>
                <p style={{ color: '#991b1b', fontWeight: '600' }}>Error</p>
                <p style={{ color: '#b91c1c', fontSize: '14px' }}>{error}</p>
              </div>
            </div>
          </div>
        )}
      </div>

      <style jsx>{`
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default SimpleCAMPreview;
